#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long long n = strtol(argv[1], &endptr, 10);

    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (n > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (n < 2) {
        puts("NONE");
        return 0;
    }

    int first = 1;
    long long original = n; // not used, kept for clarity

    for (long long p = 2; p * p <= n; ++p) {
        int exp = 0;
        while (n % p == 0) {
            ++exp;
            n /= p;
        }
        if (exp > 0) {
            if (!first) putchar(' ');
            printf("%lld^%d", p, exp);
            first = 0;
        }
    }

    if (n > 1) {
        if (!first) putchar(' ');
        printf("%lld^1", n);
    }

    putchar('\n');
    return 0;
}
